def apply(command, n):
    if command == "divide":
        return n // 2 if n % 2 == 0 else None
    if command == "add":
        return n + 1
    if command == "square":
        return n * n
    if command == "sub":
        return n - 1


def check(start, target, program, limit):
    n = start
    for digit in program:
        n = apply("divide" if digit == "1" else "add", n)
        if n is None or n <= 0:
            return False
    return n == target and len(program) <= limit
